public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                if (f.isDirectory()) {
                    forceDeleteOnExit(f);
                } else {
                    f.deleteOnExit();
                }
            }
        }
        file.deleteOnExit();
    } else {
        file.deleteOnExit();
    }
}

