protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    List<E> pathEdges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    // start with an arbitrary edge
    E current = remaining.iterator().next();
    remaining.remove(current);
    pathEdges.add(current);
    V currentVertex = graph.getEdgeTarget(current);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex) || tgt.equals(currentVertex)) {
                // orient the edge so that it continues from currentVertex
                if (src.equals(currentVertex)) {
                    currentVertex = tgt;
                } else {
                    currentVertex = src;
                }
                pathEdges.add(e);
                it.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            // cannot extend the path further; break out
            break;
        }
    }
    // If all edges were used, we have a tour; otherwise return null
    if (!remaining.isEmpty()) return null;
    return new GraphPath<>(pathEdges);
}

