private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort((List)sorted);
    for (K key : keys) {
        int idx = Collections.binarySearch((List)sorted, key);
        if (idx < 0) {
            idx = -idx - 1;
        }
        int lowerIdx = idx - 1;
        if (lowerIdx >= 0) {
            result.add(((Integer) sorted.get(lowerIdx)));
        } else {
            result.add(null);
        }
    }
    return result;
}

