public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else {
            if (c >= 0xD800 && c <= 0xDBFF && i + 1 < end) {
                char d = str.charAt(i + 1);
                if (d >= 0xDC00 && d <= 0xDFFF) {
                    size += 4;
                    i += 2;
                    continue;
                }
            }
            size += 3;
        }
        i++;
    }
    return size;
}

